create table if not exists public.schoolpro_result_domain_definitions(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 domain_type text not null check(domain_type in('affective','psychomotor')),name text not null,position integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,domain_type,name));
create table if not exists public.schoolpro_result_domain_ratings(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 student_id uuid not null references public.schoolpro_students(id) on delete cascade,term text not null,session text not null,
 definition_id uuid not null references public.schoolpro_result_domain_definitions(id) on delete cascade,rating numeric not null check(rating>=0 and rating<=10),
 rated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(student_id,term,session,definition_id));
create table if not exists public.schoolpro_result_rating_scale(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 rating numeric not null,description text not null,position integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,rating));
alter table public.schoolpro_result_domain_definitions enable row level security;alter table public.schoolpro_result_domain_ratings enable row level security;alter table public.schoolpro_result_rating_scale enable row level security;
create policy "School users read result domain definitions" on public.schoolpro_result_domain_definitions for select to authenticated using(private.has_school_access(school_id) or private.is_admin(array['super_admin'::public.user_role]));
create policy "School leaders manage result domain definitions" on public.schoolpro_result_domain_definitions for all to authenticated using(private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role])) with check(private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role]));
create policy "School users read result ratings" on public.schoolpro_result_domain_ratings for select to authenticated using(private.has_school_access(school_id) or private.is_admin(array['super_admin'::public.user_role]));
create policy "School staff manage result ratings" on public.schoolpro_result_domain_ratings for all to authenticated using(private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'teacher'::public.school_member_role,'class_teacher'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role])) with check((private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'teacher'::public.school_member_role,'class_teacher'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role])) and rated_by=auth.uid());
create policy "School users read result rating scale" on public.schoolpro_result_rating_scale for select to authenticated using(private.has_school_access(school_id) or private.is_admin(array['super_admin'::public.user_role]));
create policy "School leaders manage result rating scale" on public.schoolpro_result_rating_scale for all to authenticated using(private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role])) with check(private.has_school_access(school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role]) or private.is_admin(array['super_admin'::public.user_role]));